# https://pkg.go.dev/debug/buildinfo — Package buildinfo provides access to information embedded in a Go binary about how it was built.
require "debug/buildinfo"
# https://pkg.go.dev/debug/dwarf — Package dwarf provides access to DWARF debugging information loaded from executable files.
require "debug/dwarf"
# https://pkg.go.dev/debug/elf — Package elf implements access to ELF object files.
require "debug/elf"
# https://pkg.go.dev/debug/gosym — Package gosym implements access to the Go symbol and line number tables embedded in Go binaries generated by the gc compiler.
require "debug/gosym"
# https://pkg.go.dev/debug/macho — Package macho implements access to Mach-O object files.
require "debug/macho"
# https://pkg.go.dev/debug/pe — Package pe implements access to PE (Microsoft Windows Portable Executable) files.
require "debug/pe"
# https://pkg.go.dev/debug/plan9obj — Package plan9obj implements access to Plan 9 a.out object files.
require "debug/plan9obj"
# https://pkg.go.dev/fmt — Package fmt implements formatted I/O with functions analogous to C's printf and scanf.
require "fmt"
# https://pkg.go.dev/log — Package log implements a simple logging package.
require "log"
# https://pkg.go.dev/os — Package os provides a platform-independent interface to operating system functionality.
require "os"
module Main
  private

    # The debug/* packages parse compiled binaries. buildinfo works
    # cross-platform; elf/macho/pe/plan9obj each speak one object format
    # (only the one matching the current binary will parse successfully);
    # dwarf and gosym extract debug info once you have an ELF/Mach-O file.
    def self.runDebug
      self_, err = os.Executable()

      if err != nil
        log.Fatal(err)
      end

      debugBuildinfo(self_)
      debugFormats(self_)
      debugElfSections(self_)
      debugDwarf(self_)
      debugGosym(self_)
    end

    def self.debugBuildinfo(path)
      bi, err = buildinfo.ReadFile(path)

      if err != nil
        fmt.Println("buildinfo err:", err)

        return
      end

      fmt.Println("=== buildinfo ===")
      fmt.Println("go version:", bi.GoVersion)
      fmt.Println("main path: ", bi.Main.Path)
    end

    def self.debugFormats(path)
      # Each *.Open tries to parse the file in its native format. Only
      # the one matching the current OS's binary format will succeed.
      fmt.Println("\n=== format detection ===")
      f, err = elf.Open(path)

      if err == nil
        fmt.Printf("elf:      %s %s, %d sections\n", f.Class, f.Machine, len(f.Sections))
        f.Close()
      else
        fmt.Println("elf:      not an ELF file")
      end

      f, err = macho.Open(path)

      if err == nil
        fmt.Printf("macho:    cpu=%s, %d sections\n", f.Cpu, len(f.Sections))
        f.Close()
      else
        fmt.Println("macho:    not a Mach-O file")
      end

      f, err = pe.Open(path)

      if err == nil
        fmt.Printf("pe:       machine=0x%x, %d sections\n", f.Machine, len(f.Sections))
        f.Close()
      else
        fmt.Println("pe:       not a PE file")
      end

      f, err = plan9obj.Open(path)

      if err == nil
        fmt.Printf("plan9obj: magic=%d, %d sections\n", f.Magic, len(f.Sections))
        f.Close()
      else
        fmt.Println("plan9obj: not a Plan 9 a.out file")
      end
    end

    def self.debugElfSections(path)
      f, err = elf.Open(path)

      if err != nil
        return
      end

      defer { f.Close() }
      fmt.Println("\n=== elf sections (first 5) ===")

      f.Sections.each do |i, s|
        if i >= 5
          break
        end

        fmt.Printf("  %-24s addr=0x%08x size=%d\n", s.Name, s.Addr, s.Size)
      end
    end

    def self.debugDwarf(path)
      f, err = elf.Open(path)

      if err != nil
        return
      end

      defer { f.Close() }
      d, err = f.DWARF()

      if err != nil
        fmt.Println("\n=== dwarf ===\n  not available:", err)

        return
      end

      fmt.Println("\n=== dwarf (first 3 compilation units) ===")
      r = d.Reader()
      shown = 0

      while shown < 3
        e, err = r.Next()

        if err != nil || e == nil
          break
        end

        if e.Tag == dwarf.TagCompileUnit
          name, _ = e.Val(dwarf.AttrName)
          fmt.Println("  CU:", name)
          shown += 1
        end

        r.SkipChildren()
      end
    end

    def self.debugGosym(path)
      f, err = elf.Open(path)

      if err != nil
        return
      end

      defer { f.Close() }
      text = f.Section(".text")
      pclntab = f.Section(".gopclntab")

      if text == nil || pclntab == nil
        fmt.Println("\n=== gosym ===\n  .text or .gopclntab missing")

        return
      end

      data, err = pclntab.Data()

      if err != nil
        return
      end

      tab, err = gosym.NewTable(nil, gosym.NewLineTable(data, text.Addr))

      if err != nil
        fmt.Println("\n=== gosym ===\n  err:", err)

        return
      end

      fmt.Println("\n=== gosym (main.main location) ===")
      fn = tab.LookupFunc("main.main")

      if fn != nil
        file, line, _ = tab.PCToLine(fn.Entry)
        fmt.Printf("  main.main at %s:%d\n", file, line)
      end
    end
end
